  return frasesInteiras(t).slice(1).map((f) => f.trim()).filter((f) => f.length >= 8 && f.length <= 140 && !/^\p{Ll}/u.test(f) && !(primeira && primeira.includes(f))).slice(0, FRASES_SEGUINTES_MAX)
}
